class C { n = 1; bump() { this.n++; return this.n; } id() { return 5; } }
const c = new C();
const i = c.id;
const h = c.bump;
async function main(): Promise<void> {
  console.log(i());
  try { console.log(h()); } catch (e) { console.log("threw", (e as Error).name); }
  console.log(c.n, c.bump());
}
